import {
  defineComponent,
  Fragment,
  h,
  type Component,
  type PropType,
  type VNode,
} from 'vue';
import { motion, type Transition, type Variants } from 'motion-v';

import { useIsInView } from '../../../utils/use-is-in-view';
import {
  ReducedMotionConfig,
  transition as motionTransition,
  useMotionTokens,
  useShouldReduceMotion,
  useTempoTransition,
} from '../../../utils/motion';
import { VISUALLY_HIDDEN, splitGraphemes } from '../_text';

type Target = Record<string, unknown>;

const DEFAULT_INITIAL: Target = { x: 150, opacity: 0 };
const DEFAULT_ANIMATE: Target = { x: 0, opacity: 1 };
const DEFAULT_TRANSITION: Transition = { duration: 0.7, ease: 'easeOut' };

const DEFAULT_STAGGER = { chars: 0.05, words: 0.2, lines: 0.3 } as const;

const PIECE_STYLE = { display: 'inline-block' } as const;

const splittingTextProps = {
  text: {
    type: [String, Array] as PropType<string | string[]>,
    required: true,
  },
  type: {
    type: String as PropType<'chars' | 'words' | 'lines'>,
    default: 'chars',
  },
  initial: { type: Object as PropType<Target>, default: DEFAULT_INITIAL },
  animate: { type: Object as PropType<Target>, default: DEFAULT_ANIMATE },
  transition: Object as PropType<Transition>,
  stagger: Number,
  delay: { type: Number, default: 0 },
  inView: Boolean,
  inViewMargin: { type: String, default: '0px' },
  inViewOnce: { type: Boolean, default: true },
  disableAnimation: Boolean,
} as const;

type SplittingTextProps = {
  text: string | string[];
  type?: 'chars' | 'words' | 'lines';
  initial?: Target;
  animate?: Target;
  transition?: Transition;
  stagger?: number;
  delay?: number;
  inView?: boolean;
  inViewMargin?: string;
  inViewOnce?: boolean;
  disableAnimation?: boolean;
};

const SplittingTextContent = defineComponent({
  name: 'SplittingTextContent',
  inheritAttrs: false,
  props: splittingTextProps,
  setup(props, { attrs }) {
    const { element, isInView } = useIsInView(() => props);
    const reduce = useShouldReduceMotion();
    const tokens = useMotionTokens();
    const defaultTransition = useTempoTransition(() => DEFAULT_TRANSITION);

    return () => {
      const transition = props.transition ?? defaultTransition.value;
      const still = props.disableAnimation || reduce.value;
      const text = props.text;
      const kind = Array.isArray(text) ? 'lines' : props.type;
      const step = props.stagger ?? DEFAULT_STAGGER[kind] * tokens.value.tempo;
      const baseDelay = props.delay / 1000 + (transition.delay ?? 0);

      const itemVariants: Variants = {
        hidden: (still ? props.animate : props.initial) as Variants[string],
        visible: ((i: number) => ({
          ...props.animate,
          transition: still
            ? motionTransition.instant
            : { ...transition, delay: baseDelay + i * step },
        })) as Variants[string],
      };

      const piece = (
        content: string,
        i: number,
        style: Record<string, string> = PIECE_STYLE,
      ) =>
        h(
          motion.span as Component,
          { key: i, custom: i, variants: itemVariants, style },
          () => content,
        );

      let visual: (VNode | null)[];
      if (Array.isArray(text)) {
        visual = text.map((line, i) =>
          h(Fragment, { key: `line-${i}` }, [
            piece(line, i),
            i < text.length - 1 ? h('br') : null,
          ]),
        );
      } else if (kind === 'words') {
        const words = text.match(/\S+\s*/g) ?? [];
        visual = words.map((token, i) =>
          h(Fragment, { key: `word-${i}` }, [
            piece(token.trim(), i),
            /\s$/.test(token) ? ' ' : null,
          ]),
        );
      } else {
        let charIndex = 0;
        visual = text.split(/(\s+)/).map((token, wi) => {
          if (!token) return null;
          if (/^\s+$/.test(token))
            return h('span', { key: `space-${wi}` }, token);
          return h(
            'span',
            {
              key: `word-${wi}`,
              style: { display: 'inline-block', whiteSpace: 'nowrap' },
            },
            splitGraphemes(token).map((char) =>
              piece(char, charIndex++, { ...PIECE_STYLE, whiteSpace: 'pre' }),
            ),
          );
        });
      }

      const label = Array.isArray(text) ? text.join(' ') : text;
      return h(
        motion.span as Component,
        {
          ...attrs,
          ref: (node: unknown) => {
            element.value =
              ((node as { $el?: HTMLElement } | null)?.$el as HTMLElement) ??
              null;
          },
          'data-slot': 'splitting-text',
          initial: 'hidden',
          animate: isInView.value || still ? 'visible' : 'hidden',
        },
        () => [
          h('span', { 'aria-hidden': 'true' }, visual),
          h('span', { class: 'sr-only', style: VISUALLY_HIDDEN }, label),
        ],
      );
    };
  },
});

/** Text that comes in piece by piece: letters, words or lines. */
const SplittingText = defineComponent({
  name: 'SplittingText',
  inheritAttrs: false,
  props: splittingTextProps,
  setup(props, { attrs }) {
    return () =>
      h(ReducedMotionConfig, { remount: true }, () =>
        h(SplittingTextContent, { ...attrs, ...props }),
      );
  },
});

export { SplittingText, type SplittingTextProps };

import type { VariantProps } from "class-variance-authority"
import { cva } from "class-variance-authority"

export { default as Button } from "./Button.vue"

export const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-all disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 shrink-0 [&_svg]:shrink-0 outline-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-3 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive",
  {
    variants: {
      variant: {
        default:
          "bg-primary text-primary-foreground hover:bg-primary/90",
        destructive:
          "bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/60",
        outline:
          "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:bg-input/30 dark:border-input dark:hover:bg-input/50",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-secondary/80",
        ghost:
          "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        "default": "h-9 px-4 py-2 has-[>svg]:px-3",
        "xs": "h-6 gap-1 rounded-md px-2 text-xs has-[>svg]:px-1.5 [&_svg:not([class*='size-'])]:size-3",
        "sm": "h-8 rounded-md gap-1.5 px-3 has-[>svg]:px-2.5",
        "lg": "h-10 rounded-md px-6 has-[>svg]:px-4",
        "icon": "size-9",
        "icon-xs": "size-6 rounded-md [&_svg:not([class*='size-'])]:size-3",
        "icon-sm": "size-8",
        "icon-lg": "size-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
)
export type ButtonVariants = VariantProps<typeof buttonVariants>

import { computed, shallowRef, type ComputedRef, type Ref } from 'vue';
import { useInView } from 'motion-v';

interface UseIsInViewOptions {
  inView?: boolean;
  inViewOnce?: boolean;
  inViewMargin?: string;
}

/** Whether the element is in view, or always true when `inView` is off. */
function useIsInView(options: () => UseIsInViewOptions = () => ({})): {
  element: Ref<HTMLElement | null>;
  isInView: ComputedRef<boolean>;
} {
  const element: Ref<HTMLElement | null> = shallowRef(null);
  const { inViewOnce = false, inViewMargin = '0px' } = options();
  const inView = useInView(element, {
    once: inViewOnce,
    margin: inViewMargin as never,
  });
  return {
    element,
    isInView: computed(() => !options().inView || inView.value),
  };
}

export { useIsInView, type UseIsInViewOptions };

import {
  computed,
  defineComponent,
  Fragment,
  getCurrentInstance,
  h,
  inject,
  onBeforeUnmount,
  onMounted,
  ref,
  type ComputedRef,
  type InjectionKey,
  type Ref,
} from 'vue';
import {
  createGeneratorEasing,
  generateLinearEasing,
  MotionConfig,
  spring as springGenerator,
  useMotionConfig,
  type Transition,
} from 'motion-v';

const ease = {
  out: [0.23, 1, 0.32, 1],
  soft: [0.215, 0.61, 0.355, 1],
  draw: [0, 0, 0.58, 1],
  inOut: [0.77, 0, 0.175, 1],
  away: [0.33, 0.17, 0.67, 0.5],
  in: [0.4, 0, 1, 1],
  drawer: [0.34, 1.2, 0.64, 1],
  arrive: [0.11, 0, 0.5, 0],
  color: [0.25, 0.1, 0.25, 1],
  leave: [0, 0, 0.58, 1],
  enter: [0.25, 0.1, 0.35, 1],
  resize: [0.4, 0, 0.1, 1],
  fill: [0.4, 0, 0.2, 1],
} as const;

const spring = {
  press: { type: 'spring', stiffness: 550, damping: 30, restSpeed: 10 },
  pop: { type: 'spring', stiffness: 400, damping: 29 },
  tooltip: { type: 'spring', stiffness: 400, damping: 31 },
  dialog: { type: 'spring', stiffness: 150, damping: 25 },
  toast: { type: 'spring', stiffness: 280, damping: 24 },
  selection: { type: 'spring', stiffness: 300, damping: 30 },
  highlight: { type: 'spring', stiffness: 500, damping: 40 },
  reflow: { type: 'spring', stiffness: 500, damping: 40 },
  handoff: { type: 'spring', stiffness: 450, damping: 43 },
  morph: { type: 'spring', stiffness: 660, damping: 52 },
  height: {
    type: 'spring',
    stiffness: 300,
    damping: 30,
    bounce: 0,
    restDelta: 0.01,
  },
  slide: { type: 'spring', stiffness: 300, damping: 35, restDelta: 0.01 },
  thumb: { type: 'spring', stiffness: 300, damping: 25 },
  slider: { type: 'spring', stiffness: 400, damping: 32 },
  bounce: { type: 'spring', stiffness: 200, damping: 16 },
  glyph: { type: 'spring', stiffness: 500, damping: 45 },
  checkPop: { type: 'spring', stiffness: 500, damping: 24 },
  entrance: { type: 'spring', stiffness: 200, damping: 20 },
  progress: {
    type: 'spring',
    stiffness: 300,
    damping: 35,
    restDelta: 0.01,
    restSpeed: 0.1,
  },
  number: { type: 'spring', stiffness: 90, damping: 50 },
} as const satisfies Record<string, Transition>;

const transition = {
  menu: { duration: 0.22, ease: ease.soft },
  overlay: { duration: 0.4, ease: ease.soft },
  dialogFade: { duration: 0.4, ease: ease.soft },
  fade: { duration: 0.2, ease: ease.out },
  color: { duration: 0.2, ease: ease.color },
  reveal: { duration: 0.3, ease: ease.out },
  disclosure: { duration: 0.35, ease: ease.soft },
  panelOut: { duration: 0.15, ease: ease.leave },
  panelIn: { duration: 0.3, ease: ease.enter },
  tooltipIn: { duration: 0.34, ease: ease.enter },
  tooltipOut: { duration: 0.13, ease: ease.leave },
  panelHeight: { duration: 0.45, ease: ease.resize },
  check: { duration: 0.3, delay: 0.2, ease: ease.draw },
  uncheck: { duration: 0.3, ease: ease.draw },
  fill: { duration: 0.3, ease: ease.fill },
  popOut: { duration: 0.15, ease: ease.out },
  swap: { duration: 0.15, ease: ease.out },
  spin: { duration: 0.3, ease: ease.out },
  handoffOut: { duration: 0.22, ease: ease.soft },
  handoffIn: { duration: 0.26, ease: ease.arrive },
  dismiss: { duration: 0.2, ease: ease.away },
  shake: { duration: 0.4, ease: ease.inOut },
  drawerOut: { duration: 0.16, ease: ease.in },
  drawer: { duration: 0.4, ease: ease.drawer },
  sheet: { duration: 0.4, ease: ease.soft },
  collapse: { duration: 0.28, ease: ease.inOut },
  collapseLabel: { duration: 0.14, ease: ease.out },
  instant: { duration: 0 },
} as const satisfies Record<string, Transition>;

const scale = {
  press: 0.97,
  choice: 0.985,
  tooltip: 0.7,
  popover: 0.8,
  menu: 0.9,
  dialog: 0.8,
  icon: 0.5,
  toast: 0.96,
  fill: 0.7,
  action: 0.9,
} as const;

const blur = {
  icon: 'blur(2px)',
  tooltip: 'blur(6px)',
  disclosure: 'blur(2px)',
  surface: 'blur(4px)',
  panel: 'blur(5px)',
} as const;

const rotate = {
  icon: 90,
} as const;

const shift = {
  handoff: 6,
  navigation: 24,
  tabs: 12,
  step: 24,
  tooltip: 40,
  shake: 3,
} as const;

const stagger: { readonly stack: number } = {
  stack: 0.03,
};

const TIME_KEYS = [
  'duration',
  'visualDuration',
  'delay',
  'repeatDelay',
  'delayChildren',
];

function scaleTransition<T extends Transition | undefined>(
  value: T,
  tempo: number,
): T {
  if (!value || tempo === 1 || typeof value !== 'object') return value;
  const scaled: Record<string, unknown> = {};
  for (const [key, part] of Object.entries(value)) {
    if (typeof part === 'number' && TIME_KEYS.includes(key))
      scaled[key] = part * tempo;
    else if (typeof part === 'number' && key === 'stiffness')
      scaled[key] = part / (tempo * tempo);
    else if (typeof part === 'number' && key === 'damping')
      scaled[key] = part / tempo;
    else if (part && typeof part === 'object' && !Array.isArray(part))
      scaled[key] = scaleTransition(part as Transition, tempo);
    else scaled[key] = part;
  }
  return scaled as T;
}

function createMotionTokens(tempo = 1) {
  const pace = <T extends Record<string, Transition>>(set: T): T =>
    tempo === 1
      ? set
      : (Object.fromEntries(
          Object.entries(set).map(([role, value]) => [
            role,
            scaleTransition(value, tempo),
          ]),
        ) as T);

  return {
    tempo,
    ease,
    scale,
    blur,
    rotate,
    shift,
    stagger:
      tempo === 1
        ? stagger
        : (Object.fromEntries(
            Object.entries(stagger).map(([role, delay]) => [
              role,
              delay * tempo,
            ]),
          ) as typeof stagger),
    spring: pace(spring),
    transition: pace(transition),
  } as const;
}

type MotionTokens = ReturnType<typeof createMotionTokens>;
type CheckAnimation = 'draw' | 'pop';
type ReducedMotion = 'user' | 'never' | 'always';

const motionTokens: MotionTokens = createMotionTokens();

const MotionTokensKey: InjectionKey<Ref<MotionTokens>> = Symbol(
  'AnimateUIMotionTokens',
);
const CheckAnimationKey: InjectionKey<Ref<CheckAnimation>> = Symbol(
  'AnimateUICheckAnimation',
);
const ReducedMotionKey: InjectionKey<Ref<ReducedMotion>> = Symbol(
  'AnimateUIReducedMotion',
);

function useMotionTokens(): Ref<MotionTokens> {
  return inject(MotionTokensKey, ref(motionTokens) as Ref<MotionTokens>);
}

/** Scales a transition by the provider's `tempo`. */
function useTempoTransition<T extends Transition | undefined>(
  value: () => T,
): ComputedRef<T> {
  const tokens = useMotionTokens();
  return computed(() => scaleTransition(value(), tokens.value.tempo));
}

function useCheckAnimation(own?: () => CheckAnimation | undefined) {
  const inherited = inject(CheckAnimationKey, ref<CheckAnimation>('draw'));
  return computed(() => own?.() ?? inherited.value);
}

function useReducedMotionSetting(): ComputedRef<ReducedMotion> {
  const own = inject(ReducedMotionKey, ref<ReducedMotion>('user'));
  const config = useMotionConfig();
  return computed(() =>
    config.value.reducedMotion === 'always' ? 'always' : own.value,
  );
}

type CssTiming = { duration: number; easing: string };

const CSS_EASINGS: Record<string, string> = {
  linear: 'linear',
  easeIn: 'cubic-bezier(0.42, 0, 1, 1)',
  easeOut: 'cubic-bezier(0, 0, 0.58, 1)',
  easeInOut: 'cubic-bezier(0.42, 0, 0.58, 1)',
  circIn: 'cubic-bezier(0, 0.65, 0.55, 1)',
  circOut: 'cubic-bezier(0.55, 0, 1, 0.45)',
  backIn: 'cubic-bezier(0.31, 0.01, 0.66, -0.59)',
  backOut: 'cubic-bezier(0.33, 1.53, 0.69, 0.99)',
};

const SPRING_KEYS = [
  'stiffness',
  'damping',
  'mass',
  'bounce',
  'visualDuration',
];

function toCssEase(curve: unknown): string {
  if (
    Array.isArray(curve) &&
    curve.length === 4 &&
    curve.every(Number.isFinite)
  )
    return `cubic-bezier(${curve.join(', ')})`;
  if (typeof curve === 'string') return CSS_EASINGS[curve] ?? 'ease';
  return CSS_EASINGS.easeInOut!;
}

function toCssTiming(motionTransition: Transition): CssTiming {
  const options = motionTransition as Record<string, unknown>;
  const isSpring =
    options.type === 'spring' || SPRING_KEYS.some((key) => key in options);

  if (isSpring) {
    const springOptions =
      typeof options.duration === 'number'
        ? { ...options, duration: options.duration * 1000 }
        : options;
    const { duration, ease: curve } = createGeneratorEasing(
      springOptions,
      100,
      springGenerator,
    );
    const ms = Math.round(duration * 1000);
    return { duration: ms, easing: generateLinearEasing(curve, ms) };
  }

  const seconds = typeof options.duration === 'number' ? options.duration : 0.3;
  return {
    duration: Math.round(seconds * 1000),
    easing: toCssEase(options.ease),
  };
}

const REDUCED_MOTION_QUERY = '(prefers-reduced-motion: reduce)';

// Once the app has mounted (hydrated), later components read the setting at once.
const appMounted = () =>
  Boolean(
    (
      getCurrentInstance()?.appContext.app as
        { _container?: unknown } | undefined
    )?._container,
  );

/** False on the server and while hydrating, then follows the OS setting. */
function useShouldReduceMotion(): ComputedRef<boolean> {
  const setting = useReducedMotionSetting();
  const prefersReduced = ref(
    appMounted() && window.matchMedia(REDUCED_MOTION_QUERY).matches,
  );
  let query: MediaQueryList | undefined;
  const update = () => {
    prefersReduced.value = query?.matches ?? false;
  };
  onMounted(() => {
    query = window.matchMedia(REDUCED_MOTION_QUERY);
    update();
    query.addEventListener('change', update);
  });
  onBeforeUnmount(() => query?.removeEventListener('change', update));
  return computed(() => {
    if (setting.value === 'never') return false;
    return setting.value === 'always' || prefersReduced.value;
  });
}

const RemountOnReduce = defineComponent({
  name: 'RemountOnReduce',
  setup(_, { slots }) {
    const reduce = useShouldReduceMotion();
    return () =>
      h(Fragment, { key: reduce.value ? 'reduce' : 'full' }, slots.default?.());
  },
});

const ReducedMotionConfig = defineComponent({
  name: 'ReducedMotionConfig',
  props: { remount: Boolean },
  setup(props, { slots }) {
    const reducedMotion = useReducedMotionSetting();
    return () =>
      h(MotionConfig, { reducedMotion: reducedMotion.value }, () =>
        props.remount ? h(RemountOnReduce, null, slots) : slots.default?.(),
      );
  },
});

export {
  createMotionTokens,
  motionTokens,
  MotionTokensKey,
  CheckAnimationKey,
  ReducedMotionKey,
  useMotionTokens,
  useCheckAnimation,
  ease,
  spring,
  transition,
  scale,
  blur,
  rotate,
  shift,
  stagger,
  ReducedMotionConfig,
  useShouldReduceMotion,
  useReducedMotionSetting,
  scaleTransition,
  toCssTiming,
  useTempoTransition,
  type CssTiming,
  type MotionTokens,
  type CheckAnimation,
  type ReducedMotion,
};

const VISUALLY_HIDDEN = {
  position: 'absolute',
  width: '1px',
  height: '1px',
  padding: '0',
  margin: '-1px',
  overflow: 'hidden',
  clip: 'rect(0, 0, 0, 0)',
  whiteSpace: 'nowrap',
  borderWidth: '0',
} as const;

let segmenter: Intl.Segmenter | null | undefined;

function splitGraphemes(text: string): string[] {
  if (segmenter === undefined) {
    segmenter =
      typeof Intl !== 'undefined' && typeof Intl.Segmenter === 'function'
        ? new Intl.Segmenter(undefined, { granularity: 'grapheme' })
        : null;
  }
  if (!segmenter) return Array.from(text);
  return Array.from(segmenter.segment(text), (s) => s.segment);
}

type Grapheme = { id: string; label: string };

/** The next text's graphemes, keeping the ids of the ones it shares with the previous text, in order. */
function matchGraphemes(
  previous: readonly Grapheme[],
  labels: readonly string[],
  newId: () => string,
): Grapheme[] {
  const m = previous.length;
  const n = labels.length;
  const common = Array.from({ length: m + 1 }, () =>
    new Array<number>(n + 1).fill(0),
  );
  for (let i = m - 1; i >= 0; i--)
    for (let j = n - 1; j >= 0; j--)
      common[i]![j] =
        previous[i]!.label === labels[j]
          ? common[i + 1]![j + 1]! + 1
          : Math.max(common[i + 1]![j]!, common[i]![j + 1]!);
  const kept = new Map<number, Grapheme>();
  for (let i = 0, j = 0; i < m && j < n;) {
    if (previous[i]!.label === labels[j]) kept.set(j++, previous[i++]!);
    else if (common[i + 1]![j]! >= common[i]![j + 1]!) i++;
    else j++;
  }
  return labels.map((label, j) => kept.get(j) ?? { id: newId(), label });
}

/** Each grapheme's advance in the text as the font sets it, kerning included. */
function measureAdvances(mirror: Element, labels: readonly string[]) {
  const node = mirror.firstChild;
  if (!node) return [];
  const range = document.createRange();
  const lefts: number[] = [];
  let offset = 0;
  for (const label of labels) {
    range.setStart(node, offset);
    range.setEnd(node, offset + label.length);
    lefts.push(range.getBoundingClientRect().left);
    offset += label.length;
  }
  range.setStart(node, 0);
  range.setEnd(node, offset);
  const right = range.getBoundingClientRect().right;
  return lefts.map((left, i) => (lefts[i + 1] ?? right) - left);
}

export {
  VISUALLY_HIDDEN,
  splitGraphemes,
  matchGraphemes,
  measureAdvances,
  type Grapheme,
};

import { defineComponent, h } from 'vue';
import {
  AccordionContent as RekaAccordionContent,
  AccordionRoot as RekaAccordionRoot,
  injectAccordionItemContext,
  type AccordionContentProps as RekaAccordionContentProps,
} from 'reka-ui';

import { ReducedMotionConfig } from '../../../utils/motion';
import {
  createDisclosureContent,
  type PanelAnimationProps,
} from '../../../internal/disclosure-panel';

type AccordionContentProps = RekaAccordionContentProps & PanelAnimationProps;

const AccordionRoot = defineComponent({
  name: 'AccordionRoot',
  inheritAttrs: false,
  setup(_, { attrs, slots }) {
    return () =>
      h(ReducedMotionConfig, null, () => h(RekaAccordionRoot, attrs, slots));
  },
}) as unknown as typeof RekaAccordionRoot;

const AccordionContent = createDisclosureContent(
  'AccordionContent',
  RekaAccordionContent,
  () => injectAccordionItemContext().open,
  ['--reka-accordion-content-height', '--reka-collapsible-content-height'],
);

export {
  AccordionHeader,
  AccordionItem,
  AccordionTrigger,
