    const drawer = inject(DrawerStateKey, null);
    const variables = useTimingVariables(() => props, OVERLAY_TRANSITION);
    const element = shallowRef<HTMLElement | null>(null);
    watch(element, (node) => {
      if (drawer) drawer.overlay.value = node;
