  const onChange = (next: string) => {
    const previous = value();
    own.value = next;
    emit(next);
    if (next === previous) return;
    opened = next
      ? { item: next, at: performance.now(), byClick: clicked === next }
      : { item: '', at: -Infinity, byClick: false };
  };
  return { value, onChange };
