const NavigationMenuTrigger = highlighted(
  RekaNavigationMenuTrigger,
  'NavigationMenuTrigger',
  true,
) as unknown as typeof RekaNavigationMenuTrigger;

const NavigationMenuLink = highlighted(
  RekaNavigationMenuLink,
  'NavigationMenuLink',
  false,
