                  : null),
              },
              attrs.style,
            ],
          },
          slots,
        ),
      );
    };
  },
}) as unknown as typeof RekaNavigationMenuViewport;

const SIZE = '--reka-navigation-menu-indicator-size';
const POSITION = '--reka-navigation-menu-indicator-position';

