        const leaving = animate(el, { opacity: 0 }, exit.value);
        controls = leaving;
        void leaving.then(() => {
          if (controls !== leaving) return;
          requestAnimationFrame(() => {
            if (!visible()) present.value = false;
          });
        });
      },
      { flush: 'post' },
    );

