  const out: Record<string, unknown> = {};
  for (const declaration of normalized.split(';')) {
    const colon = declaration.indexOf(':');
    if (colon < 0) continue;
    const name = declaration.slice(0, colon).trim();
    if (name) out[name] = declaration.slice(colon + 1).trim();
