      const position = getComputedStyle(child).position;
      if (POSITIONED.includes(position)) return true;
      if (position === 'static') stack.push(child);
    }
  }
  return false;
}

function effectsOf(target: Element, timings: PanelTimings) {
  const plain = anchorsOutside(target);
  return { blur: timings.blur && !plain, move: timings.shift && !plain };
}

type PanelTimings = {
  in: CssTiming;
  out: CssTiming;
  height: CssTiming;
  follow: Transition;
  blur: boolean;
  glide: boolean;
  shift: boolean;
};

const targetsOf = (panel: HTMLElement, frame: HTMLElement | null) =>
  frame ? Array.from(frame.children) : [panel];

function fade(
  panel: HTMLElement,
  targets: Element[],
  frame: HTMLElement | null,
  keyframes: (target: Element) => Keyframe[],
  options: KeyframeAnimationOptions,
  leaving: boolean,
) {
  const animations = animationsOf(panel);
  const frames = targets.map(keyframes);
  targets.forEach((target, i) => {
    animations.fades.get(target)?.cancel();
    animations.fades.set(target, startNow(target.animate(frames[i]!, options)));
  });
  animations.targets = targets;
  animations.frame = frame;
  animations.leaving = leaving;
}

function fadeIn(
  panel: HTMLElement,
  targets: Element[],
  frame: HTMLElement | null,
  timings: PanelTimings,
  from: { way: Way | null } | null,
) {
  const animations = animationsOf(panel);
  animations.hold?.cancel();
  animations.hold = undefined;
  fade(
    panel,
    targets,
    frame,
    (target) => {
      const { blur, move } = effectsOf(target, timings);
      const start = from
        ? gone(blur, move ? from.way : null)
        : shownNow(target, blur, move);
      return [{ ...start, offset: 0 }];
    },
    {
      duration: timings.in.duration,
      easing: timings.in.easing,
      fill: 'backwards',
    },
    false,
  );
}

function fadeOut(
  panel: HTMLElement,
  targets: Element[],
  frame: HTMLElement | null,
  timings: PanelTimings,
  way: Way | null,
) {
  fade(
    panel,
    targets,
    frame,
    (target) => {
      const { blur, move } = effectsOf(target, timings);
      const away = move && way ? ([-way[0], -way[1]] as Way) : null;
      return [shownNow(target, blur, move), gone(blur, away)];
    },
    {
      duration: timings.out.duration,
      easing: timings.out.easing,
      fill: 'both',
    },
    true,
  );
}

const collapse = (a: number, b: number) =>
  Math.max(a, b, 0) + Math.min(a, b, 0);

function marginBelow(element: HTMLElement) {
  const style = getComputedStyle(element);
  const own = parseFloat(style.marginBottom) || 0;
  if (
    parseFloat(style.paddingBottom) > 0 ||
    parseFloat(style.borderBottomWidth) > 0
  )
    return own;
  const inline = element.getAttribute('style');
  const height = element.getBoundingClientRect().height;
  element.style.setProperty('transition', 'none', 'important');
  element.style.setProperty('padding-bottom', '1px', 'important');
  const one = element.getBoundingClientRect().height;
  element.style.setProperty('padding-bottom', '2px', 'important');
  const two = element.getBoundingClientRect().height;
  element.style.removeProperty('padding-bottom');
  void getComputedStyle(element).paddingBottom;
  if (inline === null) element.removeAttribute('style');
  else element.setAttribute('style', inline);
  if (Math.abs(two - one - 1) > 0.25) return own;
  return collapse(own, one - 1 - height);
}

type Extent = { height: number; margin: number };

function heightOf(element: HTMLElement) {
  const drawn = element.getBoundingClientRect().height;
  const layout = layoutSizeOf(element).height;
  return Math.abs(drawn - layout) < 0.01 ? drawn : layout;
}

const extentOf = (element: HTMLElement): Extent => ({
  height: heightOf(element),
  margin: marginBelow(element),
});

function glideHeight(
  panel: HTMLElement,
  target: HTMLElement,
  from: Extent,
  timing: CssTiming,
  follow: Transition,
) {
  const animations = animationsOf(panel);
  animations.height?.cancel();
  animations.height = undefined;
  animations.follow?.disconnect();
  animations.follow = undefined;
  const to = extentOf(target);
  if (!(to.height > 0)) return;
  const delay = (timing as CssTiming & { delay?: number }).delay ?? 0;
  const style = getComputedStyle(target);
  const own = parseFloat(style.marginBottom) || 0;
  const inset =
    style.boxSizing === 'border-box'
      ? 0
      : parseFloat(style.paddingTop) +
        parseFloat(style.paddingBottom) +
        parseFloat(style.borderTopWidth) +
        parseFloat(style.borderBottomWidth);
  const clip =
    style.overflowY === 'visible' ? { overflowY: ['clip', 'clip'] } : {};
  const run = (start: Extent, end: Extent, options: CssTiming) => {
    const sizes = [`${start.height - inset}px`, `${end.height - inset}px`];
    const margin =
      Math.abs(start.margin - own) > 0.5 || Math.abs(end.margin - own) > 0.5
        ? { marginBottom: [`${start.margin}px`, `${end.margin}px`] }
        : {};
    const animation = startNow(
      target.animate(
        { minHeight: sizes, maxHeight: sizes, ...margin, ...clip },
        { ...options, fill: 'backwards' },
      ),
    );
    animations.height = animation;
    return animation;
  };
  const same = (a: Extent, b: Extent) =>
    Math.abs(a.height - b.height) <= 0.5 &&
    Math.abs(a.margin - b.margin) <= 0.5;
  let end = to;
  let glide: Animation | null = same(from, to) ? null : run(from, to, timing);
  let waiting = delay > 0 ? glide : null;
  let rested = -Infinity;

  const check = () => {
    if (animations.height !== (glide ?? undefined)) return watch.disconnect();
    if (glide && glide === waiting && Number(glide.currentTime ?? 0) < delay) {
      const started = glide.startTime;
      glide.cancel();
      const natural = extentOf(target);
      if (!same(natural, end)) end = natural;
      glide = run(from, end, timing);
      glide.startTime = started;
      waiting = glide;
      return;
    }
    let now = end;
    let velocity = 0;
    let elapsed = 0;
    const running = !!glide && glide.playState !== 'finished';
    if (glide && running) {
      elapsed = Number(glide.currentTime ?? 0);
      now = {
        height: heightOf(target),
        margin: parseFloat(getComputedStyle(target).marginBottom) || 0,
      };
      const step = Math.min(elapsed, 8);
      glide.currentTime = elapsed - step;
      velocity = step > 0 ? (now.height - heightOf(target)) / step : 0;
      glide.cancel();
    }
    const natural = extentOf(target);
    if (same(natural, end)) {
      if (glide && running) {
        glide.play();
        glide.currentTime = elapsed;
      }
      return;
    }
    const time = performance.now();
    if (time - rested < 50) {
      animations.height = undefined;
      return watch.disconnect();
    }
    if (!running) rested = time;
    end = natural;
    const curve = curveFrom(follow, [now.height - natural.height], [velocity]);
    glide = run(now, natural, {
      duration: curve.duration,
      easing: curve.easing,
    });
  };
  const resize = new ResizeObserver(check);
  const mutation = new MutationObserver((records) => {
    for (const record of records)
      if (record.target === target)
        for (const node of record.addedNodes)
          if (node instanceof Element) resize.observe(node);
    check();
  });
  for (const child of target.children) resize.observe(child);
  mutation.observe(target, {
    childList: true,
    characterData: true,
    subtree: true,
  });
  const timer = setTimeout(
    () => watch.disconnect(),
    delay + timing.duration + toCssTiming(follow).duration,
  );
  const watch = {
    disconnect() {
      clearTimeout(timer);
      resize.disconnect();
      mutation.disconnect();
    },
  };
  animations.follow = watch;
}

function isGliding(panel: HTMLElement) {
  const height = panelAnimations.get(panel)?.height;
  return height !== undefined && isRunning(height);
}

function stopGlide(panel: HTMLElement) {
  const animations = panelAnimations.get(panel);
  if (!animations) return;
  animations.height?.cancel();
  animations.height = undefined;
  animations.follow?.disconnect();
  animations.follow = undefined;
}

const nextOf = (stage: PanelStage, token: object) =>
  [...stage.panels].find(
    ([other, entry]) => other !== token && entry.selected,
  )?.[1].element ?? null;

function leavingFrame(panel: HTMLElement, next: HTMLElement | null) {
  const animations = panelAnimations.get(panel);
  if (
    animations &&
    !animations.frame &&
    [...animations.fades.values()].some(isRunning)
  )
    return null;
  const frame = frameOf(panel);
  if (!frame) return null;
  const nextFrame = next ? frameOf(next) : null;
  return nextFrame && lookOf(nextFrame) === lookOf(frame) ? frame : null;
}

const isDisplayed = (element: HTMLElement) =>
  element.getClientRects().length > 0;

type PanelMotionOptions = {
  transition?: Transition;
  exitTransition?: Transition;
  heightTransition?: Transition;
};

/**
 * A tab panel's own motion: the panel left fades out (and slides away), the
 * next one waits for it, then fades in while the holder's height glides.
 */
function usePanelMotion(
  selected: () => boolean,
  options: () => PanelMotionOptions = () => ({}),
): {
  element: Ref<HTMLElement | null>;
  waiting: ComputedRef<boolean>;
  leaving: ComputedRef<boolean>;
} {
  const element = shallowRef<HTMLElement | null>(null);
  const token = {};
  const exit = ref<'open' | 'leaving' | 'closed'>(
    selected() ? 'open' : 'closed',
  );
  const waiting = ref(false);
  watch(
    selected,
    (now) => {
      if (now) exit.value = 'open';
      else {
        if (exit.value === 'open')
          exit.value = waiting.value ? 'closed' : 'leaving';
        waiting.value = false;
      }
    },
    { flush: 'sync' },
  );

  const reduce = useShouldReduceMotion();
  const enter = useTempoTransition(
    () => options().transition ?? motionTokens.transition.panelIn,
  );
  const leave = useTempoTransition(
    () => options().exitTransition ?? motionTokens.transition.panelOut,
  );
  const height = useTempoTransition(
    () =>
      (options().transition as { height?: Transition } | undefined)?.height ??
      options().heightTransition ??
      options().transition ??
      motionTokens.transition.panelHeight,
  );
  const quickFade = useTempoTransition(() => motionTokens.transition.fade);
  const follow = useTempoTransition(() => motionTokens.spring.morph);
  const timings = (): PanelTimings => ({
    in: toCssTiming(reduce.value ? quickFade.value : enter.value),
    out: toCssTiming(leave.value),
    height: toCssTiming(height.value),
    follow: follow.value,
    blur: true,
    glide: !reduce.value,
    shift: !reduce.value,
  });
  let stage: PanelStage | null = null;

  watch(
    () => [element.value, selected()] as const,
    ([el, isSelected], _, onCleanup) => {
      const holder = el?.parentElement;
      if (!el || !holder) return;
      const own = stageOf(holder);
      own.panels.set(token, { element: el, selected: isSelected });
      onCleanup(() => own.panels.delete(token));
    },
    { immediate: true, flush: 'post' },
  );

  watch(
    () => [selected(), waiting.value, element.value] as const,
    ([isSelected, isWaiting, el], _, onCleanup) => {
      const holder = el?.parentElement;
      if (!isSelected || !el || !holder) return;
      const own = stageOf(holder);
      stage = own;
      if (isWaiting) {
        const go = () => (waiting.value = false);
        if (!own.current) go();
        else {
          own.waiting.add(go);
          onCleanup(() => own.waiting.delete(go));
        }
        return;
      }
      if (own.current && own.current !== token) {
        waiting.value = true;
        return;
      }
      const current = timings();
      if (own.current === token) {
        const running = panelAnimations.get(el);
        if (running?.leaving)
          fadeIn(el, running.targets, running.frame, current, null);
        return;
      }
      own.current = token;
      const way = wayOf(holder, own.last, el);
      own.last = el;
      const comesIn = own.shown && own.painted;
      own.shown = true;
      const left = own.frame;
      own.frame = null;
      if (!comesIn || typeof el.animate !== 'function') return;
      const candidate = left ? frameOf(el) : null;
      const frame =
        left && candidate && lookOf(candidate) === left.look ? candidate : null;
      fadeIn(el, targetsOf(el, frame), frame, current, { way });
      if (!current.glide) return;
      if (frame && left)
        glideHeight(el, frame, left.extent, current.height, current.follow);
      else if (own.height !== undefined)
        glideHeight(el, el, own.height, current.height, current.follow);
    },
    { immediate: true, flush: 'post' },
  );

  watch(
    exit,
    (state, _, onCleanup) => {
      const el = element.value;
      if (state !== 'leaving') return;
      const own = stage;
      let cancelled = false;
      const goes = () => {
        exit.value = 'closed';
        if (own) release(own, token);
      };
      if (
        !el ||
        !own ||
        own.current !== token ||
        !own.painted ||
        !isDisplayed(el) ||
        typeof el.animate !== 'function'
      ) {
        if (el) cancelAll(el);
        if (own?.current === token) {
          own.height = undefined;
          own.frame = null;
        }
        goes();
        return;
      }
      const current = timings();
      const animations = animationsOf(el);
      animations.hold?.cancel();
      const hold = startNow(
        el.animate(
          { [HOLD_PROPERTY]: ['1', '1'] },
          { duration: current.out.duration },
        ),
      );
      animations.hold = hold;
      // reka-ui renders the next panel's content a couple of ticks after selecting it.
      void (async () => {
        for (let tick = 0; tick < 4; tick++) {
          const waited = nextOf(own, token);
          if (waited && waited.children.length > 0) break;
          await nextTick();
        }
        if (cancelled) return;
        const next = nextOf(own, token);
        const frame = leavingFrame(el, next);
        const way = el.parentElement ? wayOf(el.parentElement, el, next) : null;
        fadeOut(el, targetsOf(el, frame), frame, current, way);
      })();
      hold.finished.then(
        async () => {
          if (cancelled) return;
          const frame = panelAnimations.get(el)?.frame ?? null;
          own.height = extentOf(el);
          own.frame = frame
            ? { look: lookOf(frame), extent: extentOf(frame) }
            : null;
          goes();
          await nextTick();
          cancelAll(el);
        },
        () => {},
      );
      onCleanup(() => {
        cancelled = true;
      });
    },
    { flush: 'post' },
  );

  onBeforeUnmount(() => {
    if (stage) release(stage, token);
    if (element.value) cancelAll(element.value);
  });

  return {
    element,
    waiting: computed(() => selected() && waiting.value),
    leaving: computed(() => exit.value === 'leaving'),
  };
}

export {
  TAB_ATTRIBUTE,
  useTabsIndicator,
  usePanelMotion,
  glideHeight,
  stopGlide,
  isGliding,
  extentOf,
  heightOf,
  type TabsIndicatorOptions,
  type PanelMotionOptions,
  type Extent,
};

import {
  defineComponent,
  h,
  inject,
  onBeforeUnmount,
  onMounted,
  provide,
  ref,
  shallowRef,
  useId,
  watch,
  type InjectionKey,
  type PropType,
  type Ref,
  type VNode,
} from 'vue';
import {
  createGeneratorEasing,
  generateLinearEasing,
  spring as springGenerator,
  type Transition,
} from 'motion-v';

import {
  motionTokens,
  toCssTiming,
  useShouldReduceMotion,
  useTempoTransition,
} from '../utils/motion';
import { layoutScale } from './layout-scale';
import { staggerLeft } from './stagger';

export const HIGHLIGHT_TRANSITION = motionTokens.spring.highlight;
const FADE_TRANSITION = motionTokens.transition.color;
const RESUME_TRANSITION = motionTokens.transition.fade;

type Surface = {
  backgroundColor: string;
  backgroundImage: string;
  borderRadius: string;
};

type Offset = { x: number; y: number; scaleX: number; scaleY: number };

type Glide = {
  animation: Animation;
  ease: (progress: number) => number;
  duration: number;
  from: Offset;
};

type SurfaceHandle = {
  id: string;
  element: HTMLElement;
  item: HTMLElement;
  glide: Glide | null;
};

type Leaving = { id: string; to: HTMLElement | null; key: number };

type Start = {
  offset: Offset;
  opacity: number;
  color: string | null;
  fresh: boolean;
  velocity: Offset;
  cross: boolean;
  enters: boolean;
};

export type HighlightScope = {
  activeId: Ref<string | null>;
  leaving: Ref<readonly Leaving[]>;
  slot: string;
  light: (id: string, item: HTMLElement) => void;
  unlight: (id: string) => void;
  left: (id: string) => void;
  handOff: (item: HTMLElement, reduce: boolean) => Start;
  startOf: (id: string, item: HTMLElement, reduce: boolean) => Start;
  leavingStartOf: (id: string, item: HTMLElement, reduce: boolean) => Start;
  register: (handle: SurfaceHandle) => () => void;
  gone: (opacity: number) => void;
  paint: (surface: Surface) => Surface;
};

const ItemScopeKey: InjectionKey<HighlightScope> = Symbol(
  'AnimateUIItemHighlight',
);
const TriggerScopeKey: InjectionKey<HighlightScope> = Symbol(
  'AnimateUITriggerHighlight',
);

const without = (list: readonly Leaving[], id: string) =>
  list.some((other) => other.id === id)
    ? list.filter((other) => other.id !== id)
    : list;

function clipperOf(item: HTMLElement) {
  const body = item.ownerDocument.body;
  for (let el = item.parentElement; el && el !== body; el = el.parentElement) {
    const { overflowX, overflowY } = getComputedStyle(el);
    if (overflowX !== 'visible' || overflowY !== 'visible') return el;
  }
  return null;
}

const crossesClip = (from: HTMLElement, to: HTMLElement) =>
  clipperOf(from) !== clipperOf(to);

// Out of a clipped box into the one around it, the one leaving is cut on the
// way: it fades out under the one coming in, whole at once. Otherwise the one
// coming in fades in over the one leaving.
const comesOut = (from: HTMLElement, to: HTMLElement) => {
  const inner = clipperOf(from);
  const outer = clipperOf(to);
  return !!inner && !inner.contains(to) && (!outer || outer.contains(from));
};

function createScope(
  open: () => boolean,
  slot: string,
  reduce: () => boolean,
): HighlightScope {
  const activeId = ref<string | null>(null);
  const leaving = shallowRef<readonly Leaving[]>([]);
  let surface: SurfaceHandle | null = null;
  let key = 0;
  let painted: Surface | null = null;
  const lit = new Map<string, HTMLElement>();
  let gone: { opacity: number; at: number } | null = null;
  // Read as an item lights up, before the surface it takes over unmounts.
  const starts = new Map<string, Start>();
  // Leaving copies remount on every hand-off: they start from the surface as it is now, not once it has unmounted.
  const leavingStarts = new Map<string, Start>();
  const items = new Map<string, HTMLElement>();
  const holdStarts = (list: readonly Leaving[]) => {
    for (const other of list) {
      const item = items.get(other.id);
      if (item) leavingStarts.set(other.id, handOffFrom(item, reduce()));
    }
  };
  const handOffFrom = (item: HTMLElement, reduced: boolean) => {
    const start = handOff(surface, item, reduced);
    if (
      !surface?.element.isConnected &&
      gone &&
      performance.now() - gone.at < 120
    )
      return { ...start, opacity: gone.opacity, fresh: false };
    return start;
  };

  watch(open, (now) => {
    if (!now) return;
    activeId.value = null;
    leaving.value = [];
  });

  const activate = (id: string, item: HTMLElement) => {
    const previous = surface;
    starts.set(id, handOffFrom(item, reduce()));
    activeId.value = id;
    const moves =
      previous && previous.id !== id && previous.element.isConnected
        ? previous
        : null;
    const cross = moves !== null && crossesClip(moves.item, item);
    const k = (key += 1);
    const rest = without(leaving.value, id).filter(
      (other) => other.to !== null,
    );
    if (!moves || (!cross && rest.length === 0)) {
      leaving.value = rest;
      return;
    }
    const along = rest.map((other) => ({ ...other, to: item, key: k }));
    const next = cross
      ? [...without(along, moves.id), { id: moves.id, to: item, key: k }]
      : along;
    holdStarts(next);
    leaving.value = next;
  };

  return {
    activeId,
    leaving,
    slot,
    light: (id, item) => {
      items.set(id, item);
      lit.delete(id);
      lit.set(id, item);
      activate(id, item);
    },
    unlight: (id) => {
      if (!lit.delete(id) || activeId.value !== id) return;
      const next = [...lit].at(-1);
      if (next) {
        activate(...next);
        return;
      }
      activeId.value = null;
      const k = (key += 1);
      const fading = { id, to: null, key: k };
      holdStarts([fading]);
      leaving.value = [...without(leaving.value, id), fading];
    },
    left: (id) => {
      leaving.value = without(leaving.value, id);
    },
    handOff: handOffFrom,
    startOf: (id, item, reduced) => {
      const start = starts.get(id);
      starts.delete(id);
      return start ?? handOffFrom(item, reduced);
    },
    leavingStartOf: (id, item, reduced) => {
      const start = leavingStarts.get(id);
      leavingStarts.delete(id);
      return start ?? handOffFrom(item, reduced);
    },
    register: (handle) => {
      surface = handle;
      return () => {
        if (surface === handle) surface = null;
      };
    },
    gone: (opacity) => {
      gone = { opacity, at: performance.now() };
    },
    paint: (next) => {
      if (isBare(next)) return painted ?? next;
      painted = next;
      return next;
    },
  };
}

/** One highlight for a list of items, handed from item to item. */
export function provideHighlightScope(
  open: () => boolean,
  { shared = false }: { shared?: boolean } = {},
) {
  const parent = inject(ItemScopeKey, null);
  if (shared && parent) return parent;
  const reduce = useShouldReduceMotion();
  const scope = createScope(open, 'item-highlight', () => reduce.value);
  provide(ItemScopeKey, scope);
  return scope;
}

/** One highlight for a row of triggers (a menubar's). */
export function provideTriggerHighlightScope() {
  const reduce = useShouldReduceMotion();
  const scope = createScope(
    () => true,
    'trigger-highlight',
    () => reduce.value,
  );
  provide(TriggerScopeKey, scope);
  return scope;
}

const SURFACE_PROPERTIES = ['background-color', 'background-image'] as const;
type SavedStyle = [property: string, value: string, priority: string][];
const savedStyles = new WeakMap<HTMLElement, SavedStyle>();

function save(node: HTMLElement, properties: readonly string[]): SavedStyle {
  return properties.map((property) => [
    property,
    node.style.getPropertyValue(property),
    node.style.getPropertyPriority(property),
  ]);
}

function restore(node: HTMLElement, saved: SavedStyle) {
  for (const [property, value, priority] of saved) {
    if (value) node.style.setProperty(property, value, priority);
    else node.style.removeProperty(property);
  }
}

function clearOwnSurface(node: HTMLElement, clear: boolean) {
