          clearOwnSurface(
            el,
            now || (!interactive && blendsIn(el, readSurface(el))),
          );
          if (now === lit) return;
          lit = now;
          if (now) scope.light(id, el);
          else scope.unlight(id);
        };
        const enter = () => {
          hovered = true;
          sync();
          cancelAnimationFrame(frame);
          frame = requestAnimationFrame(sync);
        };
        const leave = () => {
          hovered = false;
          cancelAnimationFrame(frame);
          sync();
        };
