      el.addEventListener('blur', clear);
      onCleanup(() => {
        observer.disconnect();
        el.removeEventListener('focus', focus);
        el.removeEventListener('blur', clear);
        clearOwnSurface(el, false);
      });
    },
    { flush: 'post' },
  );

