    setElement: (element) => {
      if (element && element !== node.value) node.value = element;
    },
    render: () => {
      const item = node.value;
      if (!scope || !surface.value || !item) return [];
      const active = scope.activeId.value === id && !disabled();
      const leaving =
        (!disabled() && scope.leaving.value.find((other) => other.id === id)) ||
