const hidden = new WeakSet<HTMLElement>();

function hide(node: HTMLElement | null) {
  if (!node) return;
  node.style.visibility = 'hidden';
  hidden.add(node);
}

function show(node: HTMLElement | null) {
  if (!node || !hidden.has(node)) return;
  node.style.visibility = '';
