import type { Transition } from 'motion-v';

import { toCssTiming } from '../utils/motion';
import { screenScale } from './screen-scale';

type Glide = {
  animation: Animation;
  distance: number;
};

const glides = new WeakMap<Element, Glide>();

function stopGlide(element: Element) {
  glides.get(element)?.animation.cancel();
  glides.delete(element);
}

function glideFrom(
  element: HTMLElement,
  start: DOMRect,
  glide: Transition,
  end?: DOMRect,
) {
  if (typeof element.animate !== 'function') return;
  stopGlide(element);
  end ??= element.getBoundingClientRect();
  const [sx, sy] = screenScale(element.parentElement);
  const x = (start.left - end.left) / sx;
  const y = (start.top - end.top) / sy;
  if (Math.abs(x) < 0.5 && Math.abs(y) < 0.5) return;
  const { duration, easing } = toCssTiming(glide);
  const animation = element.animate(
    [{ translate: `${x}px ${y}px` }, { translate: '0px 0px' }],
    { duration, easing, composite: 'add' },
  );
  glides.set(element, { animation, distance: Math.hypot(x, y) });
  animation.finished.then(
    () =>
      glides.get(element)?.animation === animation && glides.delete(element),
    () => {},
  );
  return animation;
}

function whenLanded(element: Element, landed: () => void) {
  const glide = glides.get(element);
  let frame = 0;
  let waiting = true;
  const stop = () => {
    waiting = false;
    cancelAnimationFrame(frame);
  };
  const land = () => {
    if (!waiting) return;
    stop();
    landed();
  };
  if (!glide) {
    land();
    return stop;
  }
  const { animation, distance } = glide;
  const check = () => {
    const progress = animation.effect?.getComputedTiming().progress;
    if (progress == null || Math.abs(1 - progress) * distance < 0.5) land();
    else frame = requestAnimationFrame(check);
  };
  animation.finished.then(land, land);
  frame = requestAnimationFrame(check);
  return stop;
}

export { glideFrom, stopGlide, whenLanded };

import {
  animate,
  frame,
  motionValue,
  type MotionValue,
  type Transition,
} from 'motion-v';

import { startOf } from './momentum';

type Tracked = {
  value: MotionValue<number>;
  target: number;
  written: string | null;
  scheduled: boolean;
};

type SpringOptions = {
  transition: Transition;
  reduce: boolean;
  /** Keeps the speed it has when the target changes on the way (a resize). */
  momentum?: boolean;
};

/**
 * CSS variables (in px) on an element that spring to their targets. A target
 * is either set from code or read from what the library renders (`follow`):
 * whatever it writes is taken as the next target and the shown value written
 * back before the frame is painted.
 */
function createVarSprings(
  node: HTMLElement,
  follow: string[],
  options: () => SpringOptions,
) {
  const tracked = new Map<string, Tracked>();

  const write = (name: string) => {
    const own = tracked.get(name);
    if (!own) return;
    const value = `${own.value.get()}px`;
    own.written = value;
    if (node.style.getPropertyValue(name) !== value)
      node.style.setProperty(name, value);
  };

  const set = (name: string, to: number) => {
    const own = tracked.get(name);
    if (!own) {
      const value = motionValue(to);
      tracked.set(name, {
        value,
        target: to,
        written: null,
        scheduled: false,
      });
      value.on('change', () => write(name));
      write(name);
      return;
    }
    if (own.target === to) return;
    own.target = to;
    const { reduce } = options();
    if (reduce) {
      own.value.stop();
      own.value.jump(to);
      write(name);
      return;
    }
    // Started on the frame loop, so it moves from the frame it's shown at.
    if (!own.scheduled) {
      own.scheduled = true;
      frame.update(() => {
        own.scheduled = false;
        retarget(own);
      });
    }
  };

  const retarget = (own: Tracked) => {
    const { transition, momentum } = options();
    const to = own.target;
    if (!momentum) {
      animate(own.value, to, transition);
      return;
    }
    const velocity = own.value.getVelocity() / 1000;
    own.value.stop();
    const offset = own.value.get() - to;
    const speed = startOf(transition, [offset], [velocity]);
    animate(own.value, to, { ...transition, velocity: -offset * speed * 1000 });
  };

  const check = () => {
    for (const name of follow) {
      const raw = node.style.getPropertyValue(name).trim();
      if (raw.endsWith('px') && raw !== tracked.get(name)?.written)
        set(name, parseFloat(raw));
    }
    for (const name of tracked.keys())
      if (node.style.getPropertyValue(name) !== tracked.get(name)!.written)
        write(name);
  };

  const observer = new MutationObserver(check);
  observer.observe(node, { attributes: true, attributeFilter: ['style'] });
  check();

  return {
    set,
    stop() {
      observer.disconnect();
      for (const own of tracked.values()) own.value.stop();
    },
  };
}

export { createVarSprings };

function screenScale(element: Element | null): [number, number] {
  if (!(element instanceof HTMLElement)) return [1, 1];
  const rect = element.getBoundingClientRect();
  const ratio = (drawn: number, laid: number) =>
    laid && Math.abs(drawn - laid) >= 1 ? drawn / laid : 1;
  return [
    ratio(rect.width, element.offsetWidth),
    ratio(rect.height, element.offsetHeight),
  ];
}

function layoutHeight(element: HTMLElement) {
  const drawn = element.getBoundingClientRect().height || 0;
  return drawn / screenScale(element)[1];
}

export { layoutHeight, screenScale };
